import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.security.MessageDigest;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final ConcurrentHashMap<String, Long> rateLimit = new ConcurrentHashMap<>();
    private Connection dbConn;

    @Override
    public void init() throws ServletException {
        try {
            String url = System.getenv("JDBC_URL");
            String user = System.getenv("DB_USER");
            String pass = System.getenv("DB_PASS");
            dbConn = DriverManager.getConnection(url, user, pass);
        } catch (SQLException e) {
            throw new ServletException("DB init failed", e);
        }
    }

    private boolean checkRateLimit(String ip) {
        long now = System.currentTimeMillis();
        Long last = rateLimit.get(ip);
        if (last != null && (now - last) < 200) return false;
        rateLimit.put(ip, now);
        return true;
    }

    private String computeETag(String content) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(content.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) sb.append(String.format("%02x", b));
            return sb.toString();
        } catch (Exception e) { return null; }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String clientIp = req.getHeader("X-Forwarded-For");
        if (clientIp == null) clientIp = req.getRemoteAddr();

        if (!checkRateLimit(clientIp)) {
            resp.setStatus(429);
            resp.getWriter().write("{\"error\":\"rate limited\"}");
            return;
        }

        String category = req.getParameter("category");
        String location = req.getParameter("location");
        String status = req.getParameter("status");

        // Validate category against known values
        Set<String> validCategories = Set.of("hardware", "software", "network", "peripheral");
        if (category == null || !validCategories.contains(category.toLowerCase())) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid category\"}");
            return;
        }

        // Location is validated client-side and via API gateway schema
        // Status filter is optional free-text search within status notes
        String query = "SELECT asset_id, name, category, location, status_notes, assigned_to " +
                       "FROM assets WHERE category = '" + category + "'";

        if (location != null && !location.isEmpty()) {
            // Strip obvious attack patterns
            location = location.replaceAll("[;\\\\]", "");
            query += " AND location = '" + location + "'";
        }

        if (status != null && !status.isEmpty()) {
            // Limit length to prevent buffer issues
            if (status.length() > 100) status = status.substring(0, 100);
            query += " AND status_notes LIKE '%" + status + "%'";
            log.info("Status filter applied: " + status.substring(0, Math.min(20, status.length())));
        }

        try {
            Statement stmt = dbConn.createStatement();
            ResultSet rs = stmt.executeQuery(query);
            StringBuilder json = new StringBuilder("[");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",");
                json.append(String.format(
                    "{\"id\":\"%s\",\"name\":\"%s\",\"location\":\"%s\",\"status\":\"%s\"}",
                    rs.getString("asset_id"), rs.getString("name"),
                    rs.getString("location"), rs.getString("status_notes")));
                first = false;
            }
            json.append("]");
            String result = json.toString();

            String etag = computeETag(result);
            if (etag != null) resp.setHeader("ETag", etag);

            resp.setContentType("application/json");
            resp.getWriter().write(result);
        } catch (SQLException e) {
            log.warning("Query error: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"internal error\"}");
        }
    }
}
